        List<Shelved> books = new ArrayList<>(Arrays.asList(
                new Shelved("A", 300), new Shelved("B", 120), new Shelved("C", 300), new Shelved("D", 90)));

        check("titlesByPagesDesc", "[A, C, B, D]", String.valueOf(PageCountRanker.titlesByPagesDesc(books)));
        check("caller's list untouched", "[A, B, C, D]", titlesOf(books));
        check("shortestTitle", "D", PageCountRanker.shortestTitle(books));

