        check("titlesByPagesDesc(one book)", "[Solo]", String.valueOf(PageCountRanker.titlesByPagesDesc(one)));
        check("shortestTitle(one book)", "Solo", PageCountRanker.shortestTitle(one));

        List<Shelved> none = new ArrayList<>();
        check("titlesByPagesDesc(empty)", "[]", String.valueOf(PageCountRanker.titlesByPagesDesc(none)));
        check("shortestTitle(empty)", "", PageCountRanker.shortestTitle(none));

        List<Shelved> allEqual = Arrays.asList(new Shelved("x", 5), new Shelved("y", 5), new Shelved("z", 5));
        check("ties keep input order", "[x, y, z]", String.valueOf(PageCountRanker.titlesByPagesDesc(allEqual)));

