import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/** A book on the shelf. Provided -- do not edit. */
record Shelved(String title, int pages) { }

/**
 * TASK: Order books by a DERIVED key and then flip the direction.
 *
 * titlesByPagesDesc(books): the titles, thickest book first.
 * Build the comparator from the derived key with
 *     Comparator.comparingInt(Shelved::pages).reversed()
 * and sort a COPY -- the caller's list must come back unchanged.
 *
 * Because List.sort is stable, two books with the same page count keep the
 * order they had in the input, even after reversed().
 *   [("A",300), ("B",120), ("C",300)] -> ["A", "C", "B"]
 *
 * shortestTitle(books): the title of the book with the FEWEST pages,
 * or "" when the list is empty. Use the same key without reversing.
 */
public class PageCountRanker {

    public static List<String> titlesByPagesDesc(List<Shelved> books) {
        List<Shelved> copy = new ArrayList<>(books);
        copy.sort(Comparator.comparingInt(Shelved::pages).reversed());
        List<String> titles = new ArrayList<>();
        for (Shelved book : copy) {
            titles.add(book.title());
        }
        return titles;
    }

    public static String shortestTitle(List<Shelved> books) {
        if (books.isEmpty()) {
            return "";
        }
        Shelved thinnest = books.get(0);
        for (Shelved book : books) {
            if (Comparator.comparingInt(Shelved::pages).compare(book, thinnest) < 0) {
                thinnest = book;
            }
        }
        return thinnest.title();
    }
}
